9: // git@github.com:org/repo.git | ssh://git@github.com/org/repo.git | https://github.com/org/repo.git
10: // → https://github.com/org/repo. Unrecognized shapes → null.
11: // ponytail: any host normalizes; only github gets visibility checks server-side — GitLab when asked
12: function normalizeRemote(url) {
13:   if (!url) return null;
14:   const m = url.match(/^git@([^:/]+):(.+?)(?:\.git)?\/?$/) || url.match(/^\w+:\/\/(?:[^@/]+@)?([^:/]+)\/(.+?)(?:\.git)?\/?$/);
15:   return m ? `https://${m[1]}/${m[2]}` : null;
16: }
