411:     // ponytail: MAX(seq) is race-free only because one runner posts batches sequentially
412:     const { m: maxSeq } = await env.DB.prepare('SELECT COALESCE(MAX(seq), -1) AS m FROM run_logs WHERE run_id = ?').bind(runId).first();
